lessons.content:
/* CSS Syntax */
selector {
  property: value;
}

/* Example */
h1 {
  color: blue;
  font-size: 24px;
}

/* Element Selector */
p {
  color: green;
}

/* Class Selector */
.title {
  font-weight: bold;
}

/* ID Selector */
#main {
  background-color: yellow;
}

/* You can apply multiple properties to one selector */
h2 {
  color: red;
  text-align: center;
  margin-top: 20px;
}
